import random
import struct
from typing import List

# This generator targets a generic null-terminated byte string (NTBS) used by many Horde3D APIs.
# Goals:
# - Produce valid C strings (terminated by a single NUL) containing interesting content
# - Cover use cases: resource names, shader contexts, file paths, pipeline stage names, sampler/uniform names
# - Include variations: printable ASCII, UTF-8, path separators, pipes for multi-path, shader-like tokens, long/short, with/without extensions
# - Deterministic under seed; total size <= 4096 bytes

MAX_TOTAL_SIZE = 4096

COMMON_EXTENSIONS = [
    b".material", b".shader", b".pipeline", b".png", b".jpg", b".tga",
    b".dds", b".hdr", b".geom", b".anim", b".part", b".compute"
]

SHADER_CONTEXTS = [
    b"default", b"lighting", b"shadow", b"forward", b"deferred", b"compute",
    b"skin", b"morph", b"depth", b"gBuffer", b"post"
]

UNIFORM_NAMES = [
    b"u_Time", b"u_ViewProj", b"u_Model", b"u_NormalMatrix", b"u_Color", b"u_Params",
    b"u_LightPos", b"u_CameraPos", b"u_Tex0", b"u_Tex1", b"u_Weight"
]

SAMPLER_NAMES = [b"albedoMap", b"normalMap", b"metalRoughMap", b"emissiveMap", b"shadowMap", b"cubeMap"]

PIPELINE_TARGETS = [b"backbuffer", b"color", b"color0", b"color1", b"depth", b"hdr", b"final"]

PATH_DIRS = [
    b"Content", b"Data", b"Assets", b"Textures", b"Materials", b"Shaders", b"Pipelines",
    b"Models", b"Animations", b"Particles"
]

EXTENSIONS = [
    b".png", b".jpg", b".tga", b".dds", b".hdr", b".mat", b".shader", b".pipe", b".h3d"
]

# Some extension names to probe h3dCheckExtension
EXTENSION_PROBES = [
    b"GL_ARB_shader_storage_buffer_object", b"GL_EXT_texture_filter_anisotropic",
    b"GL_ARB_tessellation_shader", b"GL_EXT_texture_compression_s3tc", b"GL_OES_depth_texture",
    b"H3D_utility", b"H3D_compute"
]

PRINTABLE = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"


def _rand_bytes(r: random.Random, length: int) -> bytes:
    # Mix printable with occasional non-printables (excluding NUL) to exercise NTBS handling safely
    out = bytearray()
    for _ in range(length):
        if r.random() < 0.85:
            out.append(r.choice(PRINTABLE))
        else:
            # choose a byte from 1..255 excluding 0
            out.append(r.randint(1, 255))
    return bytes(out)


def _join_with_sep(parts: List[bytes], sep: bytes) -> bytes:
    return sep.join([p for p in parts if p])


def _maybe(v: bytes, prob: float, r: random.Random) -> bytes:
    return v if r.random() < prob else b""


def _make_resource_name(r: random.Random) -> bytes:
    # Names can be arbitrary NTBS; prefer readable with optional hierarchy-like namespaces
    segments = []
    seg_count = r.randint(1, 3)
    for _ in range(seg_count):
        base = bytearray()
        base.extend(_rand_bytes(r, r.randint(3, 12)))
        # Make sure we avoid embedded NUL; already ensured by _rand_bytes
        segments.append(bytes(base))
    name = b"::".join(segments)
    if r.random() < 0.6:
        name += r.choice(COMMON_EXTENSIONS)
    return name


def _make_shader_context(r: random.Random) -> bytes:
    if r.random() < 0.7:
        return r.choice(SHADER_CONTEXTS)
    # custom token-like
    return _rand_bytes(r, r.randint(3, 16))


def _make_uniform_or_sampler(r: random.Random) -> bytes:
    arr = UNIFORM_NAMES + SAMPLER_NAMES
    if r.random() < 0.7:
        return r.choice(arr)
    prefix = r.choice([b"u_", b"s_", b"g_"])
    return prefix + _rand_bytes(r, r.randint(3, 12))


def _make_pipeline_target(r: random.Random) -> bytes:
    if r.random() < 0.7:
        return r.choice(PIPELINE_TARGETS)
    return _rand_bytes(r, r.randint(3, 12))


def _make_content_dirs(r: random.Random) -> bytes:
    # contentDir is pipe-separated without trailing slashes; include both relative and nested
    count = r.randint(1, 4)
    parts = []
    for _ in range(count):
        base = r.choice(PATH_DIRS)
        if r.random() < 0.6:
            # add nested subdirs
            sub_count = r.randint(0, 3)
            subs = []
            for __ in range(sub_count):
                subs.append(_rand_bytes(r, r.randint(3, 10)))
            base = _join_with_sep([base] + subs, b"/")
        parts.append(base)
    return _join_with_sep(parts, b"|")


def _make_path_filename(r: random.Random) -> bytes:
    # For filenames used by screenshot and general paths
    root = b"" if r.random() < 0.5 else b"."
    if r.random() < 0.3:
        root = b"/"  # absolute-like
    dirs = []
    dir_count = r.randint(0, 3)
    for _ in range(dir_count):
        dirs.append(r.choice(PATH_DIRS))
    stem = _rand_bytes(r, r.randint(3, 12))
    ext = r.choice(EXTENSIONS)
    path = b"/".join(([root] if root and root != b"." else []) + dirs + [stem + ext])
    if root == b".":
        path = b"./" + path
    return path


def _make_extension_probe(r: random.Random) -> bytes:
    if r.random() < 0.7:
        return r.choice(EXTENSION_PROBES)
    # fabricate GL-style tokens
    prefix = r.choice([b"GL_", b"GL_ARB_", b"GL_EXT_", b"H3D_"])
    token = _rand_bytes(r, r.randint(6, 18))
    return prefix + token


def _blend_variants(r: random.Random) -> bytes:
    # Compose a single NTBS that can be reused across stubs; embed hint-like sections
    parts = []
    # Start with a probable resource or context
    parts.append(_maybe(_make_resource_name(r), 0.6, r))
    parts.append(_maybe(_make_shader_context(r), 0.6, r))
    parts.append(_maybe(_make_uniform_or_sampler(r), 0.5, r))
    # Occasionally include pipeline target or extension probe
    parts.append(_maybe(_make_pipeline_target(r), 0.4, r))
    parts.append(_maybe(_make_extension_probe(r), 0.4, r))
    # Sometimes include content dirs or a filename
    if r.random() < 0.5:
        parts.append(_make_content_dirs(r))
    if r.random() < 0.5:
        parts.append(_make_path_filename(r))
    # Join with safe separators that are meaningful in different contexts
    sep = r.choice([b"\n", b" ", b";", b"|", b"," ])
    data = _join_with_sep([p for p in parts if p], sep)
    # Ensure not empty
    if not data:
        data = _rand_bytes(r, r.randint(1, 16))
    # Limit to keep under MAX_TOTAL_SIZE after NUL
    return data[:MAX_TOTAL_SIZE - 1]


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose a strategy
    choice = r.random()
    if choice < 0.20:
        payload = _make_resource_name(r)
    elif choice < 0.35:
        payload = _make_shader_context(r)
    elif choice < 0.50:
        payload = _make_uniform_or_sampler(r)
    elif choice < 0.65:
        payload = _make_content_dirs(r)
    elif choice < 0.80:
        payload = _make_path_filename(r)
    elif choice < 0.90:
        payload = _make_extension_probe(r)
    else:
        payload = _blend_variants(r)

    # Add occasional extended padding with valid ASCII to test longer strings, while keeping total size <= 4096
    if r.random() < 0.3:
        pad_len = r.randint(0, max(0, 512 - len(payload)))
        if pad_len > 0:
            payload += b"_" + _rand_bytes(r, pad_len)
    payload = payload[:MAX_TOTAL_SIZE - 1]

    # Return as NTBS
    return payload + b"\x00"
